import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../../contexts/ThemeContext';

const NotificationSettings = () => {
  const { theme } = useTheme();
  const [notifications, setNotifications] = useState({
    studyReminders: true,
    taskDeadlines: true,
    achievementUnlocks: true,
    weeklyReports: false,
    focusMode: true,
  });
  
  const handleToggle = (setting) => {
    setNotifications(prev => ({
      ...prev,
      [setting]: !prev[setting]
    }));
  };
  
  const Toggle = ({ label, name, value, onChange, delay = 0 }) => (
    <motion.div 
      className="flex items-center justify-between py-3 border-b border-gray-700/30"
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ delay }}
    >
      <span className={theme.text.secondary}>{label}</span>
      <button 
        onClick={() => onChange(name)}
        className="relative"
        aria-checked={value}
        role="switch"
      >
        <motion.div 
          className={`w-12 h-6 rounded-full ${value ? 'bg-neural-600' : 'bg-gray-700'} relative`}
          animate={{ 
            backgroundColor: value ? theme.animation.nodeColor : 'rgba(55, 65, 81, 0.5)'
          }}
          transition={{ duration: 0.2 }}
        >
          {/* Track highlight effect */}
          {value && (
            <motion.div 
              className="absolute inset-0 rounded-full"
              initial={{ opacity: 0 }}
              animate={{ 
                opacity: [0.4, 0.7, 0.4]
              }}
              style={{
                boxShadow: `0 0 6px 1px ${theme.animation.highlight}`
              }}
              transition={{ duration: 2, repeat: Infinity }}
            />
          )}
          
          {/* Sliding thumb/knob */}
          <motion.div 
            className="absolute w-4 h-4 rounded-full bg-white top-1 shadow-md"
            animate={{ 
              x: value ? 'calc(100% + 0.25rem)' : '0.25rem',
            }}
            transition={{ type: "spring", stiffness: 500, damping: 30 }}
          >
            <motion.div 
              className="absolute inset-0 rounded-full bg-white"
              animate={value ? { 
                boxShadow: [
                  `0 0 0px ${theme.animation.highlight}`,
                  `0 0 4px ${theme.animation.highlight}`,
                  `0 0 0px ${theme.animation.highlight}`
                ]
              } : { boxShadow: '0 0 0 transparent' }}
              transition={{ duration: 1.5, repeat: Infinity }}
            />
          </motion.div>
          
          {/* Status indicator */}
          <div className="absolute top-0.5 text-xxs -right-5 font-mono">
            <motion.span 
              className={value ? theme.text.primary : theme.text.muted}
              animate={{ opacity: value ? 1 : 0.5 }}
            >
              {value ? 'ON' : 'OFF'}
            </motion.span>
          </div>
        </motion.div>
      </button>
    </motion.div>
  );
  
  return (
    <>
      <motion.div 
        className="absolute top-0 left-0 w-full h-px"
        style={{
          background: `linear-gradient(90deg, transparent, ${theme.animation.nodeColor}, transparent)`
        }}
        animate={{ 
          opacity: [0.2, 0.8, 0.2],
          width: ['0%', '100%', '0%']
        }}
        transition={{ duration: 4, repeat: Infinity, delay: 0.5 }}
      />
      
      <div className="p-6 relative">
        <motion.h3 
          className={`text-xl font-bold ${theme.text.primary}`}
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          Neural Notifications
        </motion.h3>
        
        <motion.p 
          className={`mt-2 ${theme.text.secondary}`}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          Control how the system communicates with you during your study sessions.
        </motion.p>
        
        <div className="mt-6 space-y-1">
          <Toggle 
            label="Study Reminders" 
            name="studyReminders" 
            value={notifications.studyReminders} 
            onChange={handleToggle}
            delay={0.3}
          />
          <Toggle 
            label="Task Deadlines" 
            name="taskDeadlines" 
            value={notifications.taskDeadlines} 
            onChange={handleToggle}
            delay={0.4}
          />
          <Toggle 
            label="Achievement Unlocks" 
            name="achievementUnlocks" 
            value={notifications.achievementUnlocks} 
            onChange={handleToggle}
            delay={0.5}
          />
          <Toggle 
            label="Weekly Reports" 
            name="weeklyReports" 
            value={notifications.weeklyReports} 
            onChange={handleToggle}
            delay={0.6}
          />
          <Toggle 
            label="Focus Mode Alerts" 
            name="focusMode" 
            value={notifications.focusMode} 
            onChange={handleToggle}
            delay={0.7}
          />
        </div>
        
        <motion.div
          className="mt-8 p-4 rounded-lg border border-gray-700/50 bg-gray-800/30"
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ delay: 0.8 }}
        >
          <div className="flex items-start space-x-3">
            <div className="mt-1 w-5 h-5 flex-shrink-0 rounded-full bg-neural-500/50 flex items-center justify-center relative">
              <span className={`text-sm ${theme.text.primary}`}>i</span>
              <motion.div 
                className="absolute inset-0 rounded-full"
                animate={{ 
                  boxShadow: [
                    `0 0 0px ${theme.animation.highlight}`,
                    `0 0 6px ${theme.animation.highlight}`,
                    `0 0 0px ${theme.animation.highlight}`
                  ]
                }}
                transition={{ duration: 3, repeat: Infinity }}
              />
            </div>
            <p className={`text-sm ${theme.text.muted}`}>
              Your notification preferences are synced with your neural profile. 
              Changes will apply immediately across all your study interfaces.
            </p>
          </div>
        </motion.div>
      </div>
    </>
  );
};

export default NotificationSettings; 