import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

// Theme showcase component to demonstrate all available themes
const ThemeShowcase = ({ onClose = () => {} }) => {
  const { themeName, switchTheme, availableThemes } = useTheme();
  const [selectedTheme, setSelectedTheme] = useState(themeName);
  
  // Handle theme selection
  const handleSelectTheme = (theme) => {
    setSelectedTheme(theme);
    // Use try-catch to prevent errors if theme doesn't exist
    try {
      switchTheme(theme);
    } catch (error) {
      console.error(`Error switching to theme: ${theme}`, error);
    }
  };

  // Theme descriptions mapping
  const themeDescriptions = {
    minimalistClean: {
      title: "Minimalist & Clean UI",
      description: "Simple layout, white or light-colored backgrounds, distraction-free interface.",
      focus: "Clarity, easy navigation, and reduced distractions."
    },
    natureCalmness: {
      title: "Nature & Calmness Theme",
      description: "Greenery, plants, soft color tones (green, blue, beige).",
      focus: "Stress-free studying, peaceful environment."
    },
    darkModeNeon: {
      title: "Dark Mode with Neon Highlights",
      description: "Dark background + glowing neon highlights (blue, green, purple).",
      focus: "Reduces eye strain, best for night study."
    },
    productivityDashboard: {
      title: "Productivity Dashboard Theme",
      description: "Clean dashboard with timers, study goals, graphs, and streaks.",
      focus: "Motivation through visual progress tracking."
    },
    gamificationAchievement: {
      title: "Gamification & Achievement-Based Theme",
      description: "XP points, badges, study streaks, rewards.",
      focus: "Makes studying engaging & fun without distractions."
    },
    retroVintage: {
      title: "Retro & Vintage Study Theme",
      description: "Warm colors (brown, beige, old-book style UI).",
      focus: "Classic and cozy study environment."
    },
    pastelGradient: {
      title: "Pastel & Soft Gradient Theme",
      description: "Soft pink, blue, purple shades with smooth transitions.",
      focus: "Relaxing, reduces eye strain, stress-free UI."
    },
    aiPoweredSmart: {
      title: "AI-Powered Smart Theme",
      description: "AI-generated personalized study recommendations, study history insights.",
      focus: "Smart tracking without distractions."
    },
    spaceFuturistic: {
      title: "Space & Futuristic Theme",
      description: "Galaxy backgrounds, deep blue tones, sci-fi inspired UI.",
      focus: "Enhances creativity & immersive study experience."
    },
    paperNotebook: {
      title: "Paper & Notebook Theme",
      description: "Handwritten font, paper-texture background, digital notes feel.",
      focus: "Gives a real notebook-like experience, perfect for note-taking."
    },
    // Include original themes too
    light: {
      title: "Light Theme",
      description: "Clean and bright interface for daytime studying.",
      focus: "High contrast, clear readability in bright environments."
    },
    dark: {
      title: "Dark Theme",
      description: "Reduced brightness for comfortable night studying.",
      focus: "Reduced eye strain in low-light environments."
    },
    ocean: {
      title: "Ocean Theme",
      description: "Calming blue tones inspired by ocean depths.",
      focus: "Relaxing atmosphere for deep concentration."
    },
    sunset: {
      title: "Sunset Theme",
      description: "Warm, inspiring colors of a beautiful sunset.",
      focus: "Creative motivation with warm, comforting colors."
    },
    cyberNeural: {
      title: "Cyber Neural Theme",
      description: "Futuristic neural network-inspired design.",
      focus: "Modern, tech-forward study environment."
    },
    quantumGlow: {
      title: "Quantum Glow Theme",
      description: "Vibrant purple tones with quantum-inspired elements.",
      focus: "Energizing colors for stimulating study sessions."
    },
    deepMind: {
      title: "Deep Mind Theme",
      description: "Dark, focused interface for deep concentration.",
      focus: "Minimal distractions and high focus."
    }
  };

  return (
    <motion.div
      className="fixed inset-0 flex items-center justify-center z-50 p-4"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>
      
      <motion.div
        className={`relative w-full max-w-4xl max-h-[90vh] overflow-y-auto rounded-xl backdrop-blur-xl bg-gradient-to-br ${
          selectedTheme.includes('light') || selectedTheme.includes('Clean') || selectedTheme.includes('Nature') || 
          selectedTheme.includes('pastelGradient') || selectedTheme.includes('paper') || selectedTheme.includes('retro')
          ? 'from-white/90 to-gray-100/90 text-gray-900 border border-gray-200'
          : 'from-gray-900/90 to-gray-800/90 text-white border border-gray-700'
        } shadow-2xl`}
        initial={{ scale: 0.9, y: 20 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.9, y: 20 }}
      >
        <div className="p-6">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-bold">Choose Your Study Theme</h2>
            <button 
              onClick={onClose}
              className="p-2 rounded-full hover:bg-gray-200/20"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="18" y1="6" x2="6" y2="18"></line>
                <line x1="6" y1="6" x2="18" y2="18"></line>
              </svg>
            </button>
          </div>
          
          <p className="mb-6">Select a theme that enhances your focus and suits your study environment.</p>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {availableThemes.map(theme => {
              const themeInfo = themeDescriptions[theme] || {
                title: theme.charAt(0).toUpperCase() + theme.slice(1),
                description: "Custom theme style",
                focus: "Personalized study experience"
              };
              
              return (
                <motion.div
                  key={theme}
                  className={`rounded-lg p-4 cursor-pointer transition-all ${
                    selectedTheme === theme 
                      ? 'ring-2 ring-offset-2 ring-blue-500 shadow-lg' 
                      : 'hover:shadow-md'
                  }`}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => handleSelectTheme(theme)}
                  style={{
                    background: theme === 'light' 
                      ? 'linear-gradient(135deg, #f0f4f8, #d9e2ec)' 
                      : theme === 'dark'
                      ? 'linear-gradient(135deg, #1a202c, #2d3748)'
                      : theme === 'ocean'
                      ? 'linear-gradient(135deg, #2c5282, #285e61)'
                      : theme === 'sunset'
                      ? 'linear-gradient(135deg, #742a2a, #5b21b6)'
                      : theme === 'cyberNeural'
                      ? 'linear-gradient(135deg, #1e1b4b, #4c1d95)'
                      : theme === 'quantumGlow'
                      ? 'linear-gradient(135deg, #581c87, #831843)'
                      : theme === 'deepMind'
                      ? 'linear-gradient(135deg, #111827, #1f2937)'
                      : theme === 'minimalistClean'
                      ? 'linear-gradient(135deg, #f8fafc, #e2e8f0)'
                      : theme === 'natureCalmness'
                      ? 'linear-gradient(135deg, #d1fae5, #bef264)'
                      : theme === 'darkModeNeon'
                      ? 'linear-gradient(135deg, #0f172a, #020617)'
                      : theme === 'productivityDashboard'
                      ? 'linear-gradient(135deg, #eff6ff, #dbeafe)'
                      : theme === 'gamificationAchievement'
                      ? 'linear-gradient(135deg, #4338ca, #7e22ce)'
                      : theme === 'retroVintage'
                      ? 'linear-gradient(135deg, #fef3c7, #fbbf24)'
                      : theme === 'pastelGradient'
                      ? 'linear-gradient(135deg, #fbcfe8, #e9d5ff, #dbeafe)'
                      : theme === 'aiPoweredSmart'
                      ? 'linear-gradient(135deg, #0f172a, #1e40af)'
                      : theme === 'spaceFuturistic'
                      ? 'linear-gradient(135deg, #020617, #1e1b4b)'
                      : theme === 'paperNotebook'
                      ? 'linear-gradient(135deg, #fffbeb, #fef3c7)'
                      : 'linear-gradient(135deg, #1a202c, #2d3748)',
                    color: theme === 'light' || theme === 'minimalistClean' || theme === 'natureCalmness' || 
                           theme === 'productivityDashboard' || theme === 'pastelGradient' || 
                           theme === 'paperNotebook' || theme === 'retroVintage'
                      ? '#1a202c' : '#ffffff'
                  }}
                >
                  <h3 className="font-bold text-lg mb-1">{themeInfo.title}</h3>
                  <p className="text-sm opacity-80 mb-2">{themeInfo.description}</p>
                  <div className="text-xs font-semibold">
                    <span className="px-2 py-1 rounded-full inline-block" style={{
                      background: 'rgba(0,0,0,0.1)',
                      backdropFilter: 'blur(5px)'
                    }}>
                      Focus: {themeInfo.focus}
                    </span>
                  </div>
                </motion.div>
              );
            })}
          </div>
          
          <div className="mt-6 flex justify-between items-center">
            <button
              onClick={onClose}
              className="px-4 py-2 rounded-lg bg-gray-500/30 hover:bg-gray-500/50 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={onClose}
              className="px-4 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 text-white transition-colors"
            >
              Apply Theme
            </button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};

export default ThemeShowcase; 