import React from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../../contexts/ThemeContext';

const ProfileForm = ({ profile, onChange, onSubmit, onCancel }) => {
  const { theme } = useTheme();
  
  const handleChange = (e) => {
    onChange(e);
  };
  
  return (
    <form onSubmit={onSubmit}>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
            School
          </label>
          <input 
            type="text" 
            name="school"
            value={profile.school}
            onChange={handleChange}
            className={`w-full px-3 py-2 ${theme.inputs} rounded-lg ${theme.focusRing} focus:outline-none focus:ring-2`}
          />
        </div>
        
        <div>
          <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
            Major
          </label>
          <input 
            type="text" 
            name="major"
            value={profile.major}
            onChange={handleChange}
            className={`w-full px-3 py-2 ${theme.inputs} rounded-lg ${theme.focusRing} focus:outline-none focus:ring-2`}
          />
        </div>
        
        <div>
          <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
            Year
          </label>
          <select 
            name="year"
            value={profile.year}
            onChange={handleChange}
            className={`w-full px-3 py-2 ${theme.inputs} rounded-lg ${theme.focusRing} focus:outline-none focus:ring-2`}
          >
            <option value="">Select your year</option>
            <option value="1st Year">1st Year</option>
            <option value="2nd Year">2nd Year</option>
            <option value="3rd Year">3rd Year</option>
            <option value="4th Year">4th Year</option>
            <option value="5th Year">5th Year</option>
            <option value="Graduate">Graduate Student</option>
            <option value="Other">Other</option>
          </select>
        </div>
      </div>
      
      <div className="mt-4">
        <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
          Bio
        </label>
        <textarea 
          name="bio"
          value={profile.bio}
          onChange={handleChange}
          rows="4"
          className={`w-full px-3 py-2 ${theme.inputs} rounded-lg ${theme.focusRing} focus:outline-none focus:ring-2`}
        ></textarea>
      </div>
      
      <div className="flex justify-end mt-4">
        <motion.button
          type="button"
          className={`px-4 py-2 ${theme.button.secondary} rounded-lg mr-2`}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={onCancel}
        >
          Cancel
        </motion.button>
        <motion.button
          type="submit"
          className={`px-4 py-2 ${theme.button.primary} rounded-lg relative overflow-hidden`}
          whileHover={{ 
            scale: 1.05,
            boxShadow: theme.animation.glow
          }}
          whileTap={{ scale: 0.95 }}
        >
          <span className="relative z-10">Save</span>
          <motion.div 
            className="absolute inset-0 opacity-50"
            style={{
              background: theme.progressBar
            }}
            animate={{ 
              x: ['-100%', '100%'],
              opacity: [0.3, 0.6, 0.3]
            }}
            transition={{ 
              duration: 2, 
              repeat: Infinity,
              repeatType: "mirror"
            }}
          />
        </motion.button>
      </div>
    </form>
  );
};

export default ProfileForm; 